      p.tile.fmt.forEach(function(f){h+='<figure class="pdp-draw furn"><div>'+tileDrawSVG(p,f)+'</div><figcaption><b>Format '+f.replace('x','×')+' cm · '+esc(p.tile.sp)+'</b><span>'+tileRes(f)+'</span></figcaption></figure>'});
