      if(p.custom&&p.limits){var L=p.limits;h+='<figure class="pdp-draw furn note"><div class="pdp-lim"><b>Po mjeri</b><span>Širina '+L.w[0]+'–'+L.w[1]+' cm</span><span>Dubina '+L.d[0]+'–'+L.d[1]+' cm</span><span>Visina '+L.h[0]+'–'+L.h[1]+' cm</span><a class="s-link" href="#pdp-cfg">Unesite svoje mjere ↑</a></div><figcaption><b>Izrađeno na centimetar</b><span>+'+PR.furniture.customPerc+'% na cijenu, razmjerno</span></figcaption></figure>'}
